INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Beschaffungsmanagement > Beschaffungsprozesse & -planung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Beschaffungsprozesse immer im Voraus geplant werden?', 2, '[{"text": "Ja", "correct": true, "because": "Planung sichert Effizienz und Verfügbarkeit"}, {"text": "Nein", "correct": false, "because": "Vorab-Planung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Beschaffungsprozesse ohne Berücksichtigung des Budgets durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Budget bestimmt Beschaffungsrahmen"}, {"text": "Ja", "correct": false, "because": "Kosten sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Lieferantenbewertung ein optionaler Schritt im Beschaffungsprozess?', 2, '[{"text": "No", "correct": true, "because": "Bewertung sorgt für Qualität und Zuverlässigkeit"}, {"text": "Ja", "correct": false, "because": "Bewertung ist Best Practice"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Beschaffungsprozesse ohne Dokumentation effizient sein?', 2, '[{"text": "Nein", "correct": true, "because": "Dokumentation sichert Nachverfolgbarkeit"}, {"text": "Ja", "correct": false, "because": "Ohne Dokumentation ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Beschaffungsplanung nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Unternehmensgrößen"}, {"text": "Ja", "correct": false, "because": "Universell erforderlich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Beschaffungsplanung am wichtigsten?', 3, '[{"text": "Bedarfsermittlung", "correct": true, "because": "Grundlage für den Prozess"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeit", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Beschaffungsplanung primär?', 2, '[{"text": "Kosteneffizienz", "correct": true, "because": "Optimiert Ausgaben"}, {"text": "Schnelligkeit", "correct": false, "because": "Sekundär"}, {"text": "Markenwahl", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument ist im Beschaffungsprozess zentral?', 2, '[{"text": "Bestellung", "correct": true, "because": "Formeller Auftrag"}, {"text": "Rechnung", "correct": false, "because": "Nachgelagert"}, {"text": "Benutzerhandbuch", "correct": false, "because": "Produktbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Beschaffungsprozesse maßgeblich?', 3, '[{"text": "Lieferantenzuverlässigkeit", "correct": true, "because": "Sichert Qualität und Termine"}, {"text": "Farbe der Produkte", "correct": false, "because": "Ästhetisch"}, {"text": "Verpackungsgröße", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil einer guten Beschaffungsplanung?', 2, '[{"text": "Zeit- und Kostenersparnis", "correct": true, "because": "Optimiert Prozesse"}, {"text": "Hohe Liefergeschwindigkeit", "correct": false, "because": "Nicht allein entscheidend"}, {"text": "Minimale Dokumentation", "correct": false, "because": "Nicht Vorteil"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zu einem typischen Beschaffungsprozess?', 4, '[{"text": "Bedarfsermittlung", "correct": true, "because": "Startpunkt"}, {"text": "Lieferantenauswahl", "correct": true, "because": "Sichert Qualität"}, {"text": "Bestellung", "correct": true, "because": "Formaler Schritt"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Beschaffungsplanung?', 3, '[{"text": "Budget", "correct": true, "because": "Bestimmt finanziellen Rahmen"}, {"text": "Zeitplan", "correct": true, "because": "Sichert Verfügbarkeit"}, {"text": "Bedarf", "correct": true, "because": "Definiert Menge und Art"}, {"text": "Lieferantengröße", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können im Beschaffungsprozess auftreten?', 3, '[{"text": "Lieferverzögerungen", "correct": true, "because": "Verzögern Projekte"}, {"text": "Kostenüberschreitungen", "correct": true, "because": "Budget belastend"}, {"text": "Qualitätsmängel", "correct": true, "because": "Beeinträchtigen Nutzung"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei der Beschaffungsplanung wichtig?', 4, '[{"text": "Bedarfsanalyse", "correct": true, "because": "Bestimmt Anforderungen"}, {"text": "Lieferantenbewertung", "correct": true, "because": "Sichert Qualität"}, {"text": "Budgetplanung", "correct": true, "because": "Finanzielle Grundlage"}, {"text": "Produktfarbe", "correct": false, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein effizienter Beschaffungsprozess?', 3, '[{"text": "Kosteneinsparung", "correct": true, "because": "Optimiert Ausgaben"}, {"text": "Zeitgewinn", "correct": true, "because": "Schnellere Verfügbarkeit"}, {"text": "Qualitätssicherung", "correct": true, "because": "Bessere Produkte"}, {"text": "Minimale Dokumentation", "correct": false, "because": "Nicht Vorteil"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Bedarfsermittlung ist der erste Schritt im Beschaffungsprozess. b) Budget spielt keine Rolle bei der Beschaffung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bedarf ja, Budget wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lieferantenbewertung sichert die Qualität im Beschaffungsprozess. b) Beschaffungsprozesse sind ohne Dokumentation effizienter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bewertung ja, Dokumentation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Beschaffungsplanung optimiert Kosten. b) Sie ist nur für große Unternehmen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten ja, für alle Größen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Lieferverzögerungen können Beschaffungsprozesse stören. b) Die Bestellung ist im Beschaffungsprozess unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verzögerungen ja, Bestellung zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine gute Beschaffungsplanung spart Zeit und Kosten. b) Lieferantenauswahl hat keinen Einfluss auf die Qualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Planung ja, Auswahl wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

